// Rule-based query understanding: turn the question into Pinecone metadata filters.
// Dates in Pinecone are stored as Unix timestamps in milliseconds.

const question = $json.question.toLowerCase();

// Start of today as Unix timestamp in milliseconds
const today = new Date();
today.setHours(0, 0, 0, 0);
const todayTimestamp = today.getTime();

let filter = {};

const mentionsEvent = /event|expo|fair|conference|trade show/.test(question);
const mentionsNews = /news|latest|announcement/.test(question);

if (mentionsEvent) {
  filter.content_type = {
    "$eq": "event"
  };

  // Upcoming events
  if (/coming up|upcoming|next|future/.test(question)) {
    filter.event_start_date = {
      "$gte": todayTimestamp
    };

  // Specific year
  } else {
    const yearMatch = question.match(/\b(20\d{2})\b/);

    if (yearMatch) {
      const year = parseInt(yearMatch[1]);

      const yearStart = new Date(year, 0, 1).getTime();
      const nextYearStart = new Date(year + 1, 0, 1).getTime();

      filter.event_start_date = {
        "$gte": yearStart,
        "$lt": nextYearStart
      };

    // Past events
    } else if (/last year|older|past|history|historical/.test(question)) {
      filter.event_start_date = {
        "$lt": todayTimestamp
      };
    }
  }

  // Prototype city extraction
  const cityMatch = question.match(/in ([a-z\s]+?)(\?|$)/);

  if (cityMatch) {
    const city = cityMatch[1].trim();

    if (
      city &&
      city.length < 30 &&
      !["the future", "the past"].includes(city)
    ) {
      filter.location_city = {
        "$eq": city.replace(/\b\w/g, c => c.toUpperCase())
      };
    }
  }

} else if (mentionsNews) {
  filter.content_type = {
    "$eq": "news"
  };
}

return [
  {
    json: {
      ...$json,
      pinecone_filter: filter
    }
  }
];

// Build the context block + source list to hand to the LLM.
const matches = $json.matches || [];
const question = $('Set Question').first().json.question;

if (matches.length === 0) {
  return [{
    json: {
      question,
      context: '',
      sources: [],
      no_results: true,
    },
  }];
}

const context = matches
  .map((m, i) => `[${i + 1}] (${m.metadata.content_type}, ${m.metadata.url})\n${m.metadata.text}`)
  .join('\n\n');

const sources = matches.map(m => m.metadata.url);

return [{ json: { question, context, sources, no_results: false } }];

